using DSAExperimentation.DataStructures.SinglyLinkedList;
namespace DSAExperimentation.Tests.LeetCodeCoverage.IntersectionOfTwoLinkedLists;
public sealed partial class IntersectionOfTwoLinkedListsTests { [Fact] public void GetIntersectionNode_SharedTail_ReturnsSharedNode(){var shared=new SinglyLinkedListNode<int>(8){Next=new(4){Next=new(5)}};var a=new SinglyLinkedListNode<int>(4){Next=new(1){Next=shared}};var b=new SinglyLinkedListNode<int>(5){Next=new(6){Next=new(1){Next=shared}}};var actual=Intersection(a,b);Assert.Same(shared,actual);} private static SinglyLinkedListNode<int>? Intersection(SinglyLinkedListNode<int>? a,SinglyLinkedListNode<int>? b){var first=a;var second=b;while(!ReferenceEquals(first,second)){first=first is null?b:first.Next;second=second is null?a:second.Next;}return first;} }
